---IMPL---
export type Cell = [number, number];

export function nextGeneration(cells: Cell[]): Cell[] {
  const isAlive = (x: number, y: number) =>
    cells.some(([cx, cy]) => cx === x && cy === y);

  const liveNeighbours = (x: number, y: number) => {
    let count = 0;
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        if (isAlive(x + dx, y + dy)) count++;
      }
    }
    return count;
  };

  const candidates: Cell[] = [];
  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const cx = x + dx;
        const cy = y + dy;
        if (!candidates.some(([px, py]) => px === cx && py === cy)) {
          candidates.push([cx, cy]);
        }
      }
    }
  }

  return candidates.filter(([x, y]) => {
    const n = liveNeighbours(x, y);
    return isAlive(x, y) ? n === 2 || n === 3 : n === 3;
  });
}
